windowclass.script:
function onInit()
self.onLockModeChanged(WindowManager.getWindowReadOnlyState(self));
itemTypeSelection();
end

function onLockModeChanged(bReadOnly)
WindowManager.callSafeControlsSetLockMode(self, { "cost", "weight", "itemdifficulty", "itemfirerate", "itemammo", "itemtype", "itemdamagedie", "itemdescription", "itemskill", "itemskillspeciality", "itemarmorreduction", "itemarmorcoverage", "itemavailability", "itemscale", "itemrange", }, bReadOnly);
parentcontrol.setVisible(WindowManager.getAnyControlVisible(self, { "cost", "weight", "itemdifficulty", "itemfirerate", "itemammo", "itemtype", "itemdamagedie", "itemdescription", "itemskill", "itemskillspeciality", "itemarmorreduction", "itemarmorcoverage", "itemavailability", "itemscale", "itemrange", }));
itemTypeSelection();
end

function itemTypeSelection()
local node = self.getDatabaseNode();
if not node then return end

-- Read and normalize item type
local sType = DB.getValue(node, "itemtype", ""):lower();

-- Weapon category list
local tWeaponTypes = {
["melee weapon"] = true,
["meleeweapon"] = true,
["explosive"] = true,
["weapon"] = true,
["knife"] = true,
["vibroblade"] = true,
["lightsaber"] = true,
["slugthrower"] = true,
["blaster"] = true,
["bowcaster"] = true,
["blasterartillery"] = true,
};

-- Category checks
local bIsWeapon = tWeaponTypes[sType] == true;
local bIsArmor = (sType == "armor");
local bIsEquipment = (sType == "equipment");

-- Treat unknown types as equipment
if not bIsWeapon and not bIsArmor and not bIsEquipment then
bIsEquipment = true;
end

-- Visibility rules
local bShowDamage     = bIsWeapon;    -- Always show for weapons, even if empty
local bShowSkill      = bIsWeapon;    -- Weapons only
local bShowArmor      = bIsArmor;     -- Armor only
local bShowRange      = bIsWeapon;    -- Weapons only
local bShowAmmo       = bIsWeapon;    -- Weapons only
local bShowRate       = bIsWeapon;    -- Weapons only
local bShowDifficulty = bIsWeapon;    -- Weapons only

-- Apply visibility
self.item_label_damage.setVisible(bShowDamage);
self.itemdamagedie.setVisible(bShowDamage);

self.item_label_skill.setVisible(bShowSkill);
self.itemskill.setVisible(bShowSkill);

self.item_label_range.setVisible(bShowRange);
self.itemrange.setVisible(bShowRange);

self.item_label_ammo.setVisible(bShowAmmo);
self.itemammo.setVisible(bShowAmmo);

self.item_label_difficulty.setVisible(bShowDifficulty);
self.itemdifficulty.setVisible(bShowDifficulty);

self.item_label_fire_rate.setVisible(bShowRate);
self.itemfirerate.setVisible(bShowRate);

self.item_label_skill_speciality.setVisible(bShowSkill);
self.itemskillspeciality.setVisible(bShowSkill);

self.item_label_armor_coverage.setVisible(bShowArmor);
self.itemarmorcoverage.setVisible(bShowArmor);

self.item_label_armor_damage_reduction.setVisible(bShowArmor);
self.itemarmorreduction.setVisible(bShowArmor);
end
